import { tags } from "typia";

/**
 * Optional filter criteria applied to orders before computing payment funnel
 * analytics.
 *
 * These filters restrict the universe of orders considered in the funnel to
 * those matching specific attributes such as status, monetary range, or
 * associated region or seller. They are evaluated on order-level data prior to
 * joining with payment transactions. When multiple filter fields are provided,
 * they are combined using logical AND semantics, so an order must satisfy all
 * supplied criteria to be included.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallPaymentFunnelOrderFilter = {
  /**
   * Optional list of allowed order statuses used to constrain the analysis
   * set.
   *
   * When provided and non-empty, only orders whose status field is included
   * in this list are considered in-scope for the analytics. The exact set of
   * supported status codes is defined by the order domain model (for example:
   * `created`, `pendingPayment`, `paid`, `fulfilled`, `cancelled`). If the
   * array is omitted or empty, no additional status-based restriction is
   * applied.
   */
  orderStatusIn?: string[] | undefined;

  /**
   * Optional lower bound on the gross order total used to filter orders by
   * monetary amount.
   *
   * Orders whose total monetary amount is strictly below this threshold are
   * excluded from the analytics. This value is expressed in the platform's
   * base currency or a configured reporting currency. When used together with
   * `maxOrderTotal`, the two values define a closed numeric range that orders
   * must fall within; callers should ensure that `minOrderTotal` is less than
   * or equal to `maxOrderTotal` when both are provided.
   */
  minOrderTotal?: (number & tags.Minimum<0>) | undefined;

  /**
   * Optional upper bound on the gross order total used to filter orders by
   * monetary amount.
   *
   * Orders whose total monetary amount exceeds this threshold are excluded
   * from the analytics. This value is expressed in the platform's base
   * currency or a configured reporting currency. When used together with
   * `minOrderTotal`, the two values define a closed numeric range that orders
   * must fall within; callers should ensure that `minOrderTotal` is less than
   * or equal to `maxOrderTotal` when both are provided.
   */
  maxOrderTotal?: (number & tags.Minimum<0>) | undefined;

  /**
   * Optional list of region codes used to filter orders by market or
   * geography.
   *
   * When provided and non-empty, only orders whose effective region (for
   * example, derived from shipping address, billing address, or explicit
   * region setting from shopping_mall_region_settings) matches one of the
   * specified codes are considered. If omitted or empty, analytics are not
   * restricted by region.
   */
  regionCodes?: string[] | undefined;

  /**
   * Optional list of seller identifiers used to constrain the analytics to
   * specific merchants.
   *
   * When provided and non-empty, only orders whose primary seller or
   * associated seller segment belongs to this set are considered in-scope.
   * This filter is typically used for seller-level performance dashboards or
   * investigations. If omitted or empty, no seller-level restriction is
   * applied and all sellers are included.
   */
  sellerIds?: (string & tags.Format<"uuid">)[] | undefined;
};
